use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::thread;

pub struct Cache {
    store: RwLock<HashMap<String, String>>,
}

impl Cache {
    pub fn new() -> Self {
        Self {
            store: RwLock::new(HashMap::new()),
        }
    }

